1	/**
2	 * pyvalues.mjs — Python runtime value model.
3	 *
4	 * Representation mapping (this mapping is a hard contract for every module):
5	 *
6	 *   Python          JavaScript
7	 *   ------------    ---------------------------------------------
8	 *   int             BigInt                (arbitrary precision)
9	 *   float           Number                (IEEE-754 double)
10	 *   bool            PyBool  (PY_TRUE / PY_FALSE singletons)
11	 *   None            PyNone  (PY_NONE singleton)
12	 *   str             string                (JS UTF-16 string)
13	 *   bytes           PyBytes  (wraps Uint8Array)
14	 *   list            PyList   (wraps Array)
15	 *   tuple           PyTuple  (wraps Array)
16	 *   set             PySet
17	 *   frozenset       PyFrozenSet
18	 *   dict            PyDict   (insertion ordered, Python hash/eq semantics)
19	 *   complex         PyComplex
20	 *   range           PyRange
21	 *   function        PyFunction / PyBuiltin
22	 *   object()        PyObject
23	 *
24	 * `bool` is deliberately NOT a JS boolean so that the YAML representer can
25	 * dispatch on exact type the way CPython's `type(data)` lookup does, while
26	 * still comparing equal to 1 / 0 for dict-key and ordering purposes.
27	 */
28	
29	/* ------------------------------------------------------------------ *
30	 * Exceptions
31	 * ------------------------------------------------------------------ */
