157	/**
158	 * Produce a string that is equal for two Python values exactly when
159	 * `a == b and hash(a) == hash(b)` holds in CPython for hashable values.
160	 * Notably 1, 1.0 and True collapse to the same key.
161	 */
162	export function hashKey(v) {
163	  if (typeof v === 'string') return 's�' + v;
164	  if (typeof v === 'bigint') return numericKey(v);
165	  if (typeof v === 'number') return numericKey(v);
166	  if (v instanceof PyBool) return numericKey(v.value ? 1n : 0n);
167	  if (v instanceof PyNone) return 'N';
168	  if (v instanceof PyEllipsis) return 'E';
169	  if (v instanceof PyBytes) {
170	    let s = 'b�';
171	    for (const b of v.bytes) s += String.fromCharCode(b);
172	    return s;
173	  }
174	  if (v instanceof PyTuple) {
175	    // Length-prefix each element so ('a','b') cannot collide with ('ab',).
176	    let s = 't�(';
177	    for (const it of v.items) {
178	      const h = hashKey(it);
179	      s += h.length + ':' + h + '';
180	    }
181	    return s + ')';
182	  }
183	  if (v instanceof PyFrozenSet) {
184	    const parts = v.keyOrder().slice().sort();
185	    return 'F�(' + parts.map((x) => x.length + ':' + x).join('') + ')';
186	  }
187	  if (v instanceof PyComplex) return 'c�' + numericKey(v.re) + '' + numericKey(v.im);
188	  if (v instanceof PyRange || v instanceof PyBuiltin || v instanceof PyFunction ||
189	      v instanceof PyObject || v instanceof PyBoundMethod) {
190	    return 'o�' + objectId(v);
191	  }
192	  if (v instanceof PyList) typeError("unhashable type: 'list'");
193	  if (v instanceof PyDict) typeError("unhashable type: 'dict'");
194	  if (v instanceof PySet) typeError("unhashable type: 'set'");
195	  return 'o�' + objectId(v);
196	}
