198	function numericKey(x) {
199	  if (typeof x === 'bigint') return 'n�' + x.toString();
200	  // Number: unify integral doubles with the matching int.
201	  if (Number.isFinite(x) && Number.isInteger(x)) return 'n�' + BigInt(x).toString();
202	  if (Number.isNaN(x)) return 'f�nan�' + objectIdOfNaN(x);
203	  if (x === Infinity) return 'f�inf';
204	  if (x === -Infinity) return 'f�-inf';
205	  return 'f�' + x.toString();
206	}
