208	// Each distinct NaN object in a dict stays distinct in CPython because
209	// `nan != nan`; approximate by making every NaN key unique.
210	let nanCounter = 0;
211	const nanIds = new WeakMap();
212	function objectIdOfNaN() {
213	  return 'nan' + ++nanCounter;
214	}
