233	export class PyDict {
234	  constructor(entries = []) {
235	    /** @type {Map<string, [any, any]>} insertion ordered */
236	    this.map = new Map();
237	    for (const [k, v] of entries) this.set(k, v);
238	  }
239	  get size() {
240	    return this.map.size;
241	  }
242	  has(k) {
243	    return this.map.has(hashKey(k));
244	  }
245	  get(k, dflt = undefined) {
246	    const e = this.map.get(hashKey(k));
247	    return e === undefined ? dflt : e[1];
248	  }
249	  set(k, v) {
250	    const h = hashKey(k);
251	    const e = this.map.get(h);
252	    if (e === undefined) this.map.set(h, [k, v]);
253	    else e[1] = v; // CPython keeps the original key object
254	  }
255	  delete(k) {
256	    return this.map.delete(hashKey(k));
257	  }
258	  /** @returns {Array<[any, any]>} */
259	  entries() {
260	    return Array.from(this.map.values(), (e) => [e[0], e[1]]);
261	  }
262	  keys() {
263	    return Array.from(this.map.values(), (e) => e[0]);
264	  }
265	  values() {
266	    return Array.from(this.map.values(), (e) => e[1]);
267	  }
268	}
