270	export class PySet {
271	  constructor(items = []) {
272	    this.map = new Map();
273	    for (const it of items) this.add(it);
274	  }
275	  get size() {
276	    return this.map.size;
277	  }
278	  add(v) {
279	    const h = hashKey(v);
280	    if (!this.map.has(h)) this.map.set(h, v);
281	  }
282	  has(v) {
283	    return this.map.has(hashKey(v));
284	  }
285	  delete(v) {
286	    return this.map.delete(hashKey(v));
287	  }
288	  values() {
289	    return Array.from(this.map.values());
290	  }
291	  keyOrder() {
292	    return Array.from(this.map.keys());
293	  }
294	}
