299	 * Type names / truthiness / equality / ordering
300	 * ------------------------------------------------------------------ */
301	
302	export function typeName(v) {
303	  if (typeof v === 'string') return 'str';
304	  if (typeof v === 'bigint') return 'int';
305	  if (typeof v === 'number') return 'float';
306	  if (v instanceof PyBool) return 'bool';
307	  if (v instanceof PyNone) return 'NoneType';
308	  if (v instanceof PyEllipsis) return 'ellipsis';
309	  if (v instanceof PyBytes) return 'bytes';
310	  if (v instanceof PyList) return 'list';
311	  if (v instanceof PyTuple) return 'tuple';
312	  if (v instanceof PyFrozenSet) return 'frozenset';
313	  if (v instanceof PySet) return 'set';
314	  if (v instanceof PyDict) return 'dict';
315	  if (v instanceof PyComplex) return 'complex';
316	  if (v instanceof PyRange) return 'range';
317	  if (v instanceof PySlice) return 'slice';
318	  if (v instanceof PyBuiltin) return 'builtin_function_or_method';
319	  if (v instanceof PyFunction) return 'function';
320	  if (v instanceof PyBoundMethod) return 'builtin_function_or_method';
321	  if (v instanceof PyObject) return 'object';
322	  return 'object';
