325	export function truthy(v) {
326	  if (v instanceof PyBool) return v.value;
327	  if (v instanceof PyNone) return false;
328	  if (typeof v === 'bigint') return v !== 0n;
329	  if (typeof v === 'number') return v !== 0;
330	  if (typeof v === 'string') return v.length > 0;
331	  if (v instanceof PyBytes) return v.bytes.length > 0;
332	  if (v instanceof PyList || v instanceof PyTuple) return v.items.length > 0;
333	  if (v instanceof PySet || v instanceof PyDict) return v.size > 0;
334	  if (v instanceof PyComplex) return v.re !== 0 || v.im !== 0;
335	  if (v instanceof PyRange) return rangeLength(v) > 0n;
336	  return true;
337	}
