339	/** True when `v` is one of int / float / bool (numeric tower we support). */
340	export const isNumeric = (v) =>
341	  typeof v === 'bigint' || typeof v === 'number' || v instanceof PyBool;
342	
343	/** Numeric value as BigInt if integral, else Number. */
344	export function numOf(v) {
345	  if (v instanceof PyBool) return v.value ? 1n : 0n;
346	  return v;
347	}
