355	export function pyEq(a, b) {
356	  if (isNumeric(a) && isNumeric(b)) return numEq(numOf(a), numOf(b));
357	  if (a instanceof PyComplex || b instanceof PyComplex) {
358	    if (!(isNumeric(a) || a instanceof PyComplex) || !(isNumeric(b) || b instanceof PyComplex))
359	      return false;
360	    const ca = a instanceof PyComplex ? a : new PyComplex(toFloat(a), 0);
361	    const cb = b instanceof PyComplex ? b : new PyComplex(toFloat(b), 0);
362	    return ca.re === cb.re && ca.im === cb.im;
363	  }
364	  if (typeof a === 'string' || typeof b === 'string') return a === b;
365	  if (a instanceof PyNone || b instanceof PyNone) return a === b;
366	  if (a instanceof PyBytes && b instanceof PyBytes) {
367	    if (a.bytes.length !== b.bytes.length) return false;
368	    for (let i = 0; i < a.bytes.length; i++) if (a.bytes[i] !== b.bytes[i]) return false;
369	    return true;
370	  }
371	  if (a instanceof PyList && b instanceof PyList) return seqEq(a.items, b.items);
372	  if (a instanceof PyTuple && b instanceof PyTuple) return seqEq(a.items, b.items);
373	  if (a instanceof PySet && b instanceof PySet) {
374	    if (a.size !== b.size) return false;
375	    for (const k of a.keyOrder()) if (!b.map.has(k)) return false;
376	    return true;
377	  }
378	  if (a instanceof PyDict && b instanceof PyDict) {
379	    if (a.size !== b.size) return false;
380	    for (const [k, v] of a.entries()) {
381	      if (!b.has(k)) return false;
382	      if (!pyEq(b.get(k), v)) return false;
383	    }
384	    return true;
385	  }
386	  return a === b;
387	}
