389	function numEq(x, y) {
390	  if (typeof x === 'bigint' && typeof y === 'bigint') return x === y;
391	  if (typeof x === 'number' && typeof y === 'number') return x === y;
392	  // mixed int/float
393	  const bi = typeof x === 'bigint' ? x : y;
394	  const fl = typeof x === 'bigint' ? y : x;
395	  if (!Number.isFinite(fl)) return false;
396	  if (!Number.isInteger(fl)) return false;
397	  return BigInt(fl) === bi;
