406	/**
407	 * Python `<`-based three-way comparison. Raises TypeError for values that
408	 * CPython refuses to order, which is what makes `sorted()` bail out inside
409	 * PyYAML's representer.
410	 */
411	export function pyCompare(a, b) {
412	  if (isNumeric(a) && isNumeric(b)) return numCompare(numOf(a), numOf(b));
413	  if (typeof a === 'string' && typeof b === 'string') return strCompare(a, b);
414	  if (a instanceof PyBytes && b instanceof PyBytes) {
415	    const x = a.bytes;
416	    const y = b.bytes;
417	    const n = Math.min(x.length, y.length);
418	    for (let i = 0; i < n; i++) if (x[i] !== y[i]) return x[i] < y[i] ? -1 : 1;
419	    return x.length === y.length ? 0 : x.length < y.length ? -1 : 1;
420	  }
421	  if (a instanceof PyTuple && b instanceof PyTuple) return seqCompare(a.items, b.items);
422	  if (a instanceof PyList && b instanceof PyList) return seqCompare(a.items, b.items);
423	  typeError(
424	    "'<' not supported between instances of '" + typeName(a) + "' and '" + typeName(b) + "'"
