428	function numCompare(x, y) {
429	  if (typeof x === 'bigint' && typeof y === 'bigint') return x < y ? -1 : x > y ? 1 : 0;
430	  const fx = typeof x === 'bigint' ? Number(x) : x;
431	  const fy = typeof y === 'bigint' ? Number(y) : y;
432	  if (Number.isNaN(fx) || Number.isNaN(fy)) return 1; // unordered; keeps sort total
433	  if (typeof x === 'bigint' || typeof y === 'bigint') {
434	    // Compare exactly when one side is a big integer.
435	    if (Number.isFinite(fx) && Number.isFinite(fy) &&
436	        Number.isInteger(fx) && Number.isInteger(fy)) {
437	      const bx = typeof x === 'bigint' ? x : BigInt(fx);
438	      const by = typeof y === 'bigint' ? y : BigInt(fy);
439	      return bx < by ? -1 : bx > by ? 1 : 0;
440	    }
441	  }
442	  return fx < fy ? -1 : fx > fy ? 1 : 0;
