445	/** Compare by Unicode code point, as CPython does. */
446	export function strCompare(a, b) {
447	  const ca = codePoints(a);
448	  const cb = codePoints(b);
449	  const n = Math.min(ca.length, cb.length);
450	  for (let i = 0; i < n; i++) if (ca[i] !== cb[i]) return ca[i] < cb[i] ? -1 : 1;
451	  return ca.length === cb.length ? 0 : ca.length < cb.length ? -1 : 1;
452	}
