454	function seqCompare(a, b) {
455	  const n = Math.min(a.length, b.length);
456	  for (let i = 0; i < n; i++) {
457	    if (!pyEq(a[i], b[i])) return pyCompare(a[i], b[i]);
458	  }
459	  return a.length === b.length ? 0 : a.length < b.length ? -1 : 1;
