462	/**
463	 * Stable sort that mirrors CPython's "abandon everything on TypeError"
464	 * behaviour: if any comparison raises, the caller sees the PyError and can
465	 * fall back to the original order.
466	 */
467	export function pySorted(items, cmp = pyCompare) {
468	  const arr = items.slice();
469	  const n = arr.length;
470	  if (n < 2) return arr;
471	  // bottom-up stable merge sort
472	  let src = arr;
473	  let dst = new Array(n);
474	  for (let width = 1; width < n; width *= 2) {
475	    for (let lo = 0; lo < n; lo += 2 * width) {
476	      const mid = Math.min(lo + width, n);
477	      const hi = Math.min(lo + 2 * width, n);
478	      let i = lo;
479	      let j = mid;
480	      let k = lo;
481	      while (i < mid && j < hi) {
482	        if (cmp(src[j], src[i]) < 0) dst[k++] = src[j++];
483	        else dst[k++] = src[i++];
484	      }
485	      while (i < mid) dst[k++] = src[i++];
486	      while (j < hi) dst[k++] = src[j++];
487	    }
488	    const t = src;
489	    src = dst;
490	    dst = t;
491	  }
492	  return src;
493	}
