495	/* ------------------------------------------------------------------ *
496	 * Code-point helpers (Python strings are sequences of code points)
497	 * ------------------------------------------------------------------ */
498	
499	/** Split a JS string into an array of code points (numbers). */
500	export function codePoints(s) {
501	  const out = [];
502	  for (let i = 0; i < s.length; ) {
503	    const c = s.charCodeAt(i);
504	    if (c >= 0xd800 && c <= 0xdbff && i + 1 < s.length) {
505	      const d = s.charCodeAt(i + 1);
506	      if (d >= 0xdc00 && d <= 0xdfff) {
507	        out.push((c - 0xd800) * 0x400 + (d - 0xdc00) + 0x10000);
508	        i += 2;
509	        continue;
510	      }
511	    }
512	    out.push(c);
513	    i += 1;
514	  }
515	  return out;
516	}
