518	/** Split a JS string into an array of single-code-point strings. */
519	export function chars(s) {
520	  const out = [];
521	  for (let i = 0; i < s.length; ) {
522	    const c = s.charCodeAt(i);
523	    if (c >= 0xd800 && c <= 0xdbff && i + 1 < s.length) {
524	      const d = s.charCodeAt(i + 1);
525	      if (d >= 0xdc00 && d <= 0xdfff) {
526	        out.push(s.slice(i, i + 2));
527	        i += 2;
528	        continue;
529	      }
530	    }
531	    out.push(s[i]);
532	    i += 1;
533	  }
534	  return out;
535	}
