537	/** Python `len()` of a string: number of code points. */
538	export function strLength(s) {
539	  let n = 0;
540	  for (let i = 0; i < s.length; i++, n++) {
541	    const c = s.charCodeAt(i);
542	    if (c >= 0xd800 && c <= 0xdbff && i + 1 < s.length) {
543	      const d = s.charCodeAt(i + 1);
544	      if (d >= 0xdc00 && d <= 0xdfff) i++;
545	    }
546	  }
547	  return n;
548	}
