550	export function fromCodePoint(cp) {
551	  if (cp <= 0xffff) return String.fromCharCode(cp);
552	  const v = cp - 0x10000;
553	  return String.fromCharCode(0xd800 + (v >> 10), 0xdc00 + (v & 0x3ff));
554	}
