556	export function rangeLength(r) {
557	  const { start, stop, step } = r;
558	  if (step > 0n) return stop > start ? (stop - start + step - 1n) / step : 0n;
559	  return stop < start ? (start - stop + (-step) - 1n) / (-step) : 0n;
560	}
561	
562	export function rangeItems(r) {
563	  const out = [];
564	  const n = rangeLength(r);
565	  for (let i = 0n; i < n; i++) out.push(r.start + i * r.step);
566	  return out;
567	}
