569	/** UTF-8 encode a JS string (surrogate pairs handled, lone surrogates -> WTF-8). */
570	export function utf8Encode(s) {
571	  const out = [];
572	  for (const cp of codePoints(s)) {
573	    if (cp < 0x80) out.push(cp);
574	    else if (cp < 0x800) out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
575	    else if (cp < 0x10000) out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
576	    else
577	      out.push(
578	        0xf0 | (cp >> 18),
579	        0x80 | ((cp >> 12) & 0x3f),
580	        0x80 | ((cp >> 6) & 0x3f),
581	        0x80 | (cp & 0x3f)
582	      );
583	  }
584	  return new Uint8Array(out);
585	}
